## 设置管理器

### settings_manager.gd (Autoload)

```gdscript
## 设置管理器
##
## 管理游戏设置（与存档分离）
class_name SettingsManager
extends Node

const SETTINGS_PATH = "user://saves/settings.cfg"

var _settings: Dictionary = {
    # 音频
    "master_volume": 1.0,
    "music_volume": 1.0,
    "sfx_volume": 1.0,

    # 视频
    "fullscreen": false,
    "vsync": true,
    "resolution_index": 0,

    # 控制
    "sensitivity": 1.0,
    "invert_y": false,

    # 游戏
    "language": "auto",
    "subtitles": true,
    "screen_shake": true
}

var _config: ConfigFile

func _ready() -> void:
    _config = ConfigFile.new()
    load_settings()

func load_settings() -> void:
    if _config.load(SETTINGS_PATH) == OK:
        for key in _settings.keys():
            if _config.has_section_key("settings", key):
                _settings[key] = _config.get_value("settings", key)

    apply_settings(_settings)

func save_settings() -> void:
    for key in _settings.keys():
        _config.set_value("settings", key, _settings[key])

    _config.save(SETTINGS_PATH)

func apply_settings(settings: Dictionary) -> void:
    _settings.merge(settings, true)

    # 应用音频设置
    AudioServer.set_bus_volume_db(
        AudioServer.get_bus_index("Master"),
        linear_to_db(_settings.master_volume)
    )
    AudioServer.set_bus_volume_db(
        AudioServer.get_bus_index("Music"),
        linear_to_db(_settings.music_volume)
    )
    AudioServer.set_bus_volume_db(
        AudioServer.get_bus_index("SFX"),
        linear_to_db(_settings.sfx_volume)
    )

    # 应用视频设置
    if _settings.fullscreen:
        DisplayServer.window_set_mode(DisplayServer.WINDOW_MODE_FULLSCREEN)
    else:
        DisplayServer.window_set_mode(DisplayServer.WINDOW_MODE_WINDOWED)

    DisplayServer.window_set_vsync_mode(
        DisplayServer.VSYNC_ENABLED if _settings.vsync else DisplayServer.VSYNC_DISABLED
    )

func get_setting(key: String) -> Variant:
    return _settings.get(key)

func set_setting(key: String, value: Variant) -> void:
    _settings[key] = value

func get_all_settings() -> Dictionary:
    return _settings.duplicate()

func reset_to_defaults() -> void:
    _settings = {
        "master_volume": 1.0,
        "music_volume": 1.0,
        "sfx_volume": 1.0,
        "fullscreen": false,
        "vsync": true,
        "resolution_index": 0,
        "sensitivity": 1.0,
        "invert_y": false,
        "language": "auto",
        "subtitles": true,
        "screen_shake": true
    }
    apply_settings(_settings)
    save_settings()
```

